def test_list_email_templates_returns_bundled():
    from microsoft_mcp.tools import list_email_templates

    templates = list_email_templates.fn()
    names = [(t["category"], t["name"]) for t in templates]
    # Bundled templates must include these
    assert ("calendar", "meeting") in names
    assert ("calendar", "interview") in names
    assert ("email", "followup") in names


def test_list_email_templates_category_filter():
    from microsoft_mcp.tools import list_email_templates

    calendar = list_email_templates.fn(category="calendar")
    assert all(t["category"] == "calendar" for t in calendar)
    assert any(t["name"] == "meeting" for t in calendar)

    email = list_email_templates.fn(category="email")
    assert all(t["category"] == "email" for t in email)
    assert any(t["name"] == "followup" for t in email)


