def _draft_message(draft_id: str, **overrides):
    draft = {
        "id": draft_id,
        "subject": "Draft subject",
        "from": {"emailAddress": {"name": "Me", "address": "me@example.com"}},
        "toRecipients": [{"emailAddress": {"address": "alice@example.com"}}],
        "ccRecipients": [],
        "bccRecipients": [],
        "body": {"contentType": "html", "content": "<p>body</p>"},
        "bodyPreview": "body",
        "conversationId": f"conv-{draft_id}",
        "webLink": f"https://outlook.office.com/mail/deeplink/compose/{draft_id}",
        "createdDateTime": "2026-04-02T10:00:00Z",
        "lastModifiedDateTime": "2026-04-02T10:01:00Z",
        "isDraft": True,
        "isRead": True,
    }
    draft.update(overrides)
    return draft


@patch("microsoft_mcp.tools.graph")
def test_create_email_draft_with_template(mock_graph, monkeypatch):
    """Rendering email/followup via template= produces correct HTML body in POST payload."""
    monkeypatch.setenv("MICROSOFT_MCP_DEFAULT_SIGNATURE", "")
    monkeypatch.setenv("MICROSOFT_MCP_REPLY_SIGNATURE", "")
    monkeypatch.setenv("MICROSOFT_MCP_SIGNATURES_DIR", "")

    from microsoft_mcp.tools import create_email_draft

    mock_graph.request.return_value = _draft_message("d-tpl-1")

    result = create_email_draft.fn(
        draft_type="new",
        to_recipients=["alice@example.com"],
        subject="Follow up",
        template="email/followup",
        template_data={
            "recipient_name": "Alice",
            "sender_name": "Bob",
            "context": "our demo call",
        },
    )

    assert result["status"] == "draft_created"
    assert result["draft_id"] == "d-tpl-1"

    # Verify the POST body payload contains rendered HTML
    call_args = mock_graph.request.call_args
    assert call_args[0][0] == "POST"
    assert call_args[0][1] == "/me/messages"
    posted_body = call_args[1]["json"]["body"]
    assert posted_body["contentType"] == "html"
    assert "Alice" in posted_body["content"]
    assert "Bob" in posted_body["content"]
    assert "our demo call" in posted_body["content"]


@patch("microsoft_mcp.tools.graph")
def test_create_email_draft_template_overrides_body(mock_graph, monkeypatch):
    """When template= is supplied, explicit body= is ignored."""
    monkeypatch.setenv("MICROSOFT_MCP_DEFAULT_SIGNATURE", "")
    monkeypatch.setenv("MICROSOFT_MCP_REPLY_SIGNATURE", "")
    monkeypatch.setenv("MICROSOFT_MCP_SIGNATURES_DIR", "")

    from microsoft_mcp.tools import create_email_draft

    mock_graph.request.return_value = _draft_message("d-tpl-2")

    create_email_draft.fn(
        draft_type="new",
        to_recipients=["alice@example.com"],
        body="THIS SHOULD BE IGNORED",
        template="email/followup",
        template_data={
            "recipient_name": "Carol",
            "sender_name": "Dave",
            "context": "our last meeting",
        },
    )

    call_args = mock_graph.request.call_args
    posted_content = call_args[1]["json"]["body"]["content"]
    assert "THIS SHOULD BE IGNORED" not in posted_content
    assert "Carol" in posted_content


